import { Address } from '@solana/kit';
import { i as U512BeBytes, f as U256 } from './types-C_V_CaKK.js';
import { Y as Year, M as Month, D as Day, H as Hour, a as Minute, S as Second } from './types-D1jDUjfN.js';
